function build(M) {
  const prof = [];
  const N = 40;
  for (let i = 0; i <= N; i++) {
    const t = i / N;
    const x = -4 + 8 * t;
    let r;
    if (t > 0.85) { const u = (t - 0.85) / 0.15; r = 0.8 * Math.sqrt(Math.max(0, 1 - u * u)); }
    else if (t < 0.35) { const u = t / 0.35; r = 0.12 + 0.68 * Math.sin(u * Math.PI / 2); }
    else r = 0.8;
    prof.push([r, x]);
  }
  prof[N][0] = 0;
  const hull = M.T(M.lathe(prof, 40), {rz: -90});
  const seams = [], rivets = [];
  for (let k = 0; k < 7; k++) {
    const x = -1.4 + k * 0.75;
    seams.push(M.T(M.torus(0.805, 0.012, 40, 6), {pos: [x, 0, 0], rz: 90}));
    for (let j = 0; j < 16; j++) {
      const a = j / 16 * Math.PI * 2;
      rivets.push(M.T(M.sphere(0.02, 6, 4), {pos: [x + 0.06, Math.cos(a) * 0.805, Math.sin(a) * 0.805]}));
    }
  }
  const tailCap = M.T(M.cyl(0.13, 0.06, 24, 0), {pos: [-4, 0, 0], rz: 90});
  const keel = M.box(4.6, 0.04, 0.08, -0.82, 0.3);
  return [
    {material: "dark_steel", look: "solid", mesh: M.merge([hull, keel])},
    {material: "steel", look: "solid", mesh: M.merge(seams.concat(rivets, [tailCap]))}
  ];
}

function build(M) {
  const o = [];
  const n = 12;
  for (let i = 0; i <= n; i++) {
    const t = i / n * Math.PI;
    o.push([0.35 + 0.42 * Math.sin(t), -0.27 * Math.cos(t)]);
  }
  o.push([-0.78, 0.22], [-0.78, -0.22]);
  const body = M.T(M.extrude(o, 1.05), {pos: [0, -0.075, 0]});
  const cap = M.T(M.extrude(o, 0.04), {pos: [0, 0.47, 0], s: [1.02, 1, 1.05]});
  const base = M.box(1.6, 0.08, 0.6, -0.6);
  const rails = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n * Math.PI;
    const x = 0.35 + 0.38 * Math.sin(t), z = -0.24 * Math.cos(t);
    rails.push(M.pipe([x, 0.49, z], [x, 0.58, z], 0.008, 6));
  }
  for (const s of [-1, 1]) {
    rails.push(M.pipe([-0.74, 0.58, 0.2 * s], [0.35, 0.58, 0.24 * s], 0.01, 6));
    for (let x = -0.7; x < 0.35; x += 0.25) rails.push(M.pipe([x, 0.49, 0.21 * s], [x, 0.58, 0.21 * s], 0.008, 6));
  }
  for (let i = 0; i < n; i++) {
    const a = i / n * Math.PI, b = (i + 1) / n * Math.PI;
    rails.push(M.pipe([0.35 + 0.38 * Math.sin(a), 0.58, -0.24 * Math.cos(a)], [0.35 + 0.38 * Math.sin(b), 0.58, -0.24 * Math.cos(b)], 0.01, 6));
  }
  const win = [];
  for (const s of [-1, 1]) for (let k = 0; k < 3; k++) {
    win.push(M.T(M.cyl(0.04, 0.02, 20, 0), {pos: [0.25 + k * 0.13, 0.33, s * (0.255 + 0.01)], rx: 90}));
  }
  const mast = [M.cyl(0.05, 0.12, 20, 0.47), M.T(M.cyl(0.04, 0.1, 16, 0.47), {pos: [-0.3, 0, 0]})];
  return [
    {material: "dark_steel", look: "solid", mesh: M.merge([body, cap, base])},
    {material: "steel", look: "solid", mesh: M.merge(rails.concat(mast))},
    {material: "glass", look: "glass", mesh: M.merge(win)}
  ];
}

function build(M) {
  const base = M.cyl(0.07, 0.04, 32, 0);
  const collar = M.torus(0.06, 0.012, 32, 10);
  const collar2 = M.T(M.torus(0.05, 0.008, 32, 8), {pos: [0, 0.3, 0]});
  const tube = M.cyl(0.04, 0.62, 32, 0.04);
  const neck = M.frustum(0.04, 0.05, 0.03, 32, 0.63);
  const head = M.box(0.13, 0.12, 0.1, 0.66, 0.005);
  const cap = M.box(0.12, 0.02, 0.09, 0.78, 0);
  const lens = M.T(M.cyl(0.035, 0.012, 32, 0), {pos: [0.07, 0.72, 0], rz: -90});
  const rim = M.T(M.torus(0.036, 0.006, 24, 8), {pos: [0.072, 0.72, 0], rz: 90});
  return [
    {material: "steel", look: "solid", mesh: M.merge([tube, neck, head, collar2])},
    {material: "dark_steel", look: "solid", mesh: M.merge([base, M.T(collar, {pos: [0, 0.04, 0]}), cap, rim])},
    {material: "glass", look: "glass", mesh: lens}
  ];
}

function build(M) {
  const L = 1.4, R = 0.5, cl = L/2 - R;
  const prof = [];
  for (let i = 0; i <= 12; i++) { const a = -Math.PI/2 + i*Math.PI/24; prof.push([R*Math.cos(a), -cl + R*Math.sin(a)]); }
  for (let i = 12; i <= 24; i++) { const a = -Math.PI/2 + i*Math.PI/24; prof.push([R*Math.cos(a), cl + R*Math.sin(a)]); }
  prof[0][0] = 0; prof[prof.length-1][0] = 0;
  const body = M.T(M.lathe(prof, 40), {rz: -90});
  const bands = [];
  for (const x of [-0.35, 0, 0.35]) bands.push(M.T(M.torus(R, 0.025, 40, 8), {pos: [x, 0, 0], rz: 90}));
  const holes = [];
  for (let i = 0; i < 6; i++) holes.push(M.T(M.cyl(0.04, 0.03, 16, 0), {pos: [-0.45 + i*0.18, -R + 0.015, 0], rx: 180}));
  const pipe = M.merge([M.cyl(0.06, 0.15, 20, R - 0.02), M.T(M.torus(0.07, 0.02, 20, 8), {pos: [0, R + 0.13, 0]})]);
  const valve = M.merge([M.cyl(0.09, 0.05, 24, R + 0.13), M.cyl(0.03, 0.04, 12, R + 0.18)]);
  const cradle = [];
  for (const x of [-0.35, 0.35]) cradle.push(M.box(0.08, 0.2, 0.7, -0.6, x));
  return [
    {material: "red", look: "solid", mesh: body},
    {material: "dark_steel", look: "solid", mesh: M.merge([...bands, ...cradle])},
    {material: "dark_steel", look: "solid", mesh: M.merge(holes)},
    {material: "steel", look: "solid", mesh: M.merge([pipe, valve])}
  ];
}

function build(M) {
  const base = M.cyl(0.15, 0.03, 36, 0);
  const rim = M.T(M.torus(0.13, 0.012, 36, 10), {pos: [0, 0.03, 0]});
  const stub = M.lathe([[0.07,0.03],[0.07,0.14],[0.085,0.14],[0.085,0.155],[0.055,0.155],[0.055,0.03]], 32);
  const bolts = [];
  for (let i = 0; i < 8; i++) {
    const a = i * Math.PI / 4;
    bolts.push(M.cyl(0.012, 0.015, 12, 0.03));
    bolts[i] = M.T(bolts[i], {pos: [Math.cos(a)*0.12, 0, Math.sin(a)*0.12]});
  }
  const flap = M.T(M.cyl(0.09, 0.015, 32, 0), {pos: [0.01, 0.16, 0], rz: 25});
  const hinge = M.pipe([-0.09, 0.165, -0.05], [-0.09, 0.165, 0.05], 0.012, 16);
  const lug = M.box(0.03, 0.03, 0.08, 0.14, -0.09);
  return [
    {material: "dark_steel", look: "solid", mesh: M.merge([base])},
    {material: "gold", look: "solid", mesh: M.merge([rim, stub, flap])},
    {material: "steel", look: "solid", mesh: M.merge([...bolts, hinge, lug])}
  ];
}

function build(M) {
  const tanks = [], caps = [], dark = [], pipes = [];
  const r = 0.085, L = 0.95;
  const pos = [[0.1, -0.1], [0.1, 0.1], [0.29, -0.1], [0.29, 0.1]];
  const prof = [[0, -L/2 - 0.06], [r*0.6, -L/2 - 0.05], [r, -L/2 + 0.02], [r, L/2 - 0.02], [r*0.6, L/2 + 0.05], [0.025, L/2 + 0.07], [0, L/2 + 0.07]];
  for (const [y, z] of pos) {
    const yy = y - 0.2;
    tanks.push(M.T(M.lathe(prof, 32), {pos: [-0.05, yy, z], rz: -90}));
    caps.push(M.T(M.cyl(0.03, 0.07, 20, 0), {pos: [L/2 + 0.01, yy, z], rz: -90}));
    caps.push(M.T(M.cyl(0.04, 0.025, 20, 0), {pos: [L/2 + 0.07, yy, z], rz: -90}));
    pipes.push(M.pipe([L/2 + 0.09, yy, z], [0.6, yy, z], 0.012, 10));
    pipes.push(M.pipe([0.56, yy, z], [0.56, 0.17, z*0.5], 0.012, 10));
  }
  pipes.push(M.pipe([0.56, 0.17, -0.06], [0.56, 0.17, 0.06], 0.018, 12));
  for (const x of [-0.4, 0.15]) {
    dark.push(M.box(0.05, 0.4, 0.4, -0.2, x));
    dark.push(M.T(M.torus(0.0, 0.0, 3, 3), {pos: [x, 0, 0]}));
  }
  return [
    {material: "blue", look: "solid", mesh: M.merge(tanks)},
    {material: "steel", look: "solid", mesh: M.merge(caps)},
    {material: "copper", look: "solid", mesh: M.merge(pipes)},
    {material: "dark_steel", look: "solid", mesh: M.merge(dark)}
  ];
}
